<?php

declare(strict_types=1);

namespace Lite\Framework\Console;

use PDO;

/**
 * Exports all database/migrations/*.php into a clean MySQL/MariaDB .sql file
 * for 1-click phpMyAdmin import on Shared Hosting plans without SSH access.
 */
final class MigrationSqlExporter
{
    /**
     * Capture DDL statements generated by all migrations in MySQL dialect.
     *
     * @return array{sql: string, migrations: list<string>, statements: int}
     */
    public function export(string $migrationsPath): array
    {
        $recorder = new class extends PDO {
            /** @var list<string> */
            public array $statements = [];

            public function __construct()
            {
                // Intentionally bypass parent PDO network connection; record MySQL DDL locally.
            }

            public function getAttribute(int $attribute): mixed
            {
                if ($attribute === PDO::ATTR_DRIVER_NAME) {
                    return 'mysql';
                }

                return null;
            }

            public function exec(string $statement): int|false
            {
                $trimmed = trim($statement);
                if ($trimmed !== '') {
                    $this->statements[] = rtrim($trimmed, ';') . ';';
                }
                return 0;
            }

            public function query(string $query, ?int $fetchMode = null, mixed ...$fetchModeArgs): \PDOStatement|false
            {
                // Simulate empty schema checks (e.g. SHOW COLUMNS) so ALTER statements are emitted cleanly
                return false;
            }

            public function prepare(string $query, array $options = []): \PDOStatement|false
            {
                $trimmed = trim($query);
                return new class ($this, $trimmed) extends \PDOStatement {
                    public function __construct(
                        private readonly object $recorder,
                        private readonly string $query
                    ) {
                    }

                    public function execute(?array $params = null): bool
                    {
                        $sql = $this->query;
                        if (is_array($params)) {
                            foreach ($params as $k => $v) {
                                $placeholder = str_starts_with((string)$k, ':') ? (string)$k : ':' . $k;
                                $quoted = "'" . str_replace("'", "''", (string)$v) . "'";
                                $sql = str_replace($placeholder, $quoted, $sql);
                            }
                        }
                        if ($sql !== '') {
                            $this->recorder->statements[] = rtrim($sql, ';') . ';';
                        }
                        return true;
                    }

                    public function fetchColumn(int $column = 0): mixed
                    {
                        return false;
                    }
                };
            }
        };

        $lines = [
            '-- LitePlatform Shared Hosting MySQL/MariaDB Migration Bundle',
            '-- Generated at: ' . date('Y-m-d H:i:s'),
            '-- Import directly via cPanel / DirectAdmin phpMyAdmin (no SSH required).',
            '',
            'SET NAMES utf8mb4;',
            'SET FOREIGN_KEY_CHECKS = 0;',
            '',
            'CREATE TABLE IF NOT EXISTS migrations (',
            '    id BIGINT AUTO_INCREMENT PRIMARY KEY,',
            '    migration VARCHAR(255) NOT NULL UNIQUE,',
            '    executed_at DATETIME DEFAULT CURRENT_TIMESTAMP',
            ') ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;',
            '',
        ];

        $files = is_dir($migrationsPath) ? (glob(rtrim($migrationsPath, '/\\') . '/*.php') ?: []) : [];
        sort($files);

        $exportedMigrations = [];
        $statementCount = 0;

        foreach ($files as $file) {
            $name = basename($file, '.php');
            $recorder->statements = [];

            $migration = require $file;
            if (is_object($migration) && method_exists($migration, 'up')) {
                $migration->up($recorder);
            }

            $lines[] = "-- Migration: {$name}";
            foreach ($recorder->statements as $stmt) {
                $lines[] = $stmt;
                $statementCount++;
            }
            $escapedName = str_replace("'", "''", $name);
            $lines[] = "INSERT IGNORE INTO migrations (migration) VALUES ('{$escapedName}');";
            $lines[] = '';
            $exportedMigrations[] = $name;
        }

        $lines[] = 'SET FOREIGN_KEY_CHECKS = 1;';
        $lines[] = '';

        return [
            'sql'        => implode("\n", $lines),
            'migrations' => $exportedMigrations,
            'statements' => $statementCount,
        ];
    }

    /**
     * Export and write SQL file to disk.
     *
     * @return array{path: string, migrations: list<string>, statements: int}
     */
    public function exportToFile(string $migrationsPath, string $outputPath): array
    {
        $result = $this->export($migrationsPath);
        $dir = dirname($outputPath);
        if (!is_dir($dir)) {
            mkdir($dir, 0755, true);
        }

        file_put_contents($outputPath, $result['sql']);

        return [
            'path'       => $outputPath,
            'migrations' => $result['migrations'],
            'statements' => $result['statements'],
        ];
    }
}
